create table room_inventory (id bigserial primary key, hotel_id varchar(64) not null, room_type_id varchar(64) not null, stay_date date not null, total_rooms integer not null check(total_rooms>=0), available_rooms integer not null check(available_rooms>=0), nightly_rate numeric(12,2) not null check(nightly_rate>0), currency varchar(3) not null, version bigint not null default 0, constraint uk_inventory_day unique(hotel_id,room_type_id,stay_date), check(available_rooms<=total_rooms));
create table reservations (id varchar(64) primary key, guest_id varchar(255) not null, hotel_id varchar(64) not null, room_type_id varchar(64) not null, check_in date not null, check_out date not null, room_count integer not null, adult_count integer not null, child_count integer not null, total_amount numeric(12,2) not null, currency varchar(3) not null, status varchar(32) not null, idempotency_key varchar(128) not null, created_at timestamp with time zone not null, version bigint not null default 0, constraint uk_reservation_idempotency unique(idempotency_key), check(check_out>check_in));
create index idx_reservation_guest on reservations(guest_id,created_at desc);
